insert into public.curated_courses (id, slug, title, description)
insert into public.curated_course_nodes (id, course_id, parent_id, node_type, title, description, sort_order)
values
  ('4cfbffd4-869d-4db6-813b-3115d549553a', 'd3e4f5a6-7b8c-4e93-8f23-4a5b6c7d8e33', null, 'topic'::public.curated_course_node_type, 'Defining Deviance, Norms, and Sanctions', 'This opening unit establishes deviance as a social relationship between behavior, norms, audiences, and consequences. Students learn that deviance is not simply behavior that is unusual or harmful; it is behavior interpreted through rules, power, culture, and social reaction.', 0),
  ('c89595e7-3ea0-40f8-b552-81ad57dd76cd', 'd3e4f5a6-7b8c-4e93-8f23-4a5b6c7d8e33', '4cfbffd4-869d-4db6-813b-3115d549553a', 'subtopic'::public.curated_course_node_type, 'Norms and normative orders', 'Students examine how formal and informal expectations define acceptable conduct across settings.', 0),
  ('c6561dad-0390-4f0f-8961-14174edd65c7', 'd3e4f5a6-7b8c-4e93-8f23-4a5b6c7d8e33', 'c89595e7-3ea0-40f8-b552-81ad57dd76cd', 'concept'::public.curated_course_node_type, 'Folkways, mores, and laws', null, 0),
  ('9e624fb0-c987-4d61-a357-18075ffbcdca', 'd3e4f5a6-7b8c-4e93-8f23-4a5b6c7d8e33', 'c89595e7-3ea0-40f8-b552-81ad57dd76cd', 'concept'::public.curated_course_node_type, 'Context-dependent norms', null, 1),
  ('83532fe4-75fa-4582-8f62-6d4b518f9dd7', 'd3e4f5a6-7b8c-4e93-8f23-4a5b6c7d8e33', 'c89595e7-3ea0-40f8-b552-81ad57dd76cd', 'concept'::public.curated_course_node_type, 'Norm conflict and pluralism', null, 2),
  ('f549a360-ad90-4732-ad52-436bc0a90133', 'd3e4f5a6-7b8c-4e93-8f23-4a5b6c7d8e33', '4cfbffd4-869d-4db6-813b-3115d549553a', 'subtopic'::public.curated_course_node_type, 'Sanctions and social reaction', 'This subtopic introduces praise, stigma, exclusion, punishment, treatment, and surveillance as responses to rule-breaking.', 1),
  ('d16c39c3-5a15-436c-9a2c-f877767e3044', 'd3e4f5a6-7b8c-4e93-8f23-4a5b6c7d8e33', 'f549a360-ad90-4732-ad52-436bc0a90133', 'concept'::public.curated_course_node_type, 'Positive and negative sanctions', null, 0),
  ('4e806031-f294-45f4-a4c5-1c387e8e978f', 'd3e4f5a6-7b8c-4e93-8f23-4a5b6c7d8e33', 'f549a360-ad90-4732-ad52-436bc0a90133', 'concept'::public.curated_course_node_type, 'Informal and formal sanctions', null, 1),
  ('80bd2e40-2f8b-4ea8-825f-a56c8c946f07', 'd3e4f5a6-7b8c-4e93-8f23-4a5b6c7d8e33', 'f549a360-ad90-4732-ad52-436bc0a90133', 'concept'::public.curated_course_node_type, 'Consequences for identity and opportunity', null, 2),
  ('3f32962b-8355-4e58-a641-8594df095631', 'd3e4f5a6-7b8c-4e93-8f23-4a5b6c7d8e33', '4cfbffd4-869d-4db6-813b-3115d549553a', 'subtopic'::public.curated_course_node_type, 'Relativity of deviance', 'Students learn why definitions of deviance vary across time, place, institutions, and groups.', 2),
  ('ad383965-a184-42ce-9ae2-9ea5c78796a1', 'd3e4f5a6-7b8c-4e93-8f23-4a5b6c7d8e33', '3f32962b-8355-4e58-a641-8594df095631', 'concept'::public.curated_course_node_type, 'Historical change', null, 0),
  ('2b0254c9-73d7-4120-a2b0-e68bc94853ff', 'd3e4f5a6-7b8c-4e93-8f23-4a5b6c7d8e33', '3f32962b-8355-4e58-a641-8594df095631', 'concept'::public.curated_course_node_type, 'Subcultural difference', null, 1),
  ('06024366-e170-4488-8aef-e27a05b2974a', 'd3e4f5a6-7b8c-4e93-8f23-4a5b6c7d8e33', '3f32962b-8355-4e58-a641-8594df095631', 'concept'::public.curated_course_node_type, 'Power and boundary-making', null, 2),
  ('9ad9b9a7-fd88-4b51-9308-59174dce992e', 'd3e4f5a6-7b8c-4e93-8f23-4a5b6c7d8e33', null, 'topic'::public.curated_course_node_type, 'The Sociological Study of Deviance and Social Control', 'This unit introduces deviance as a central sociological problem: how societies create rules, mark boundaries, respond to difference, and organize conformity. It also prepares students to evaluate theories and evidence rather than relying on stereotypes.', 1),
  ('001d019e-41eb-4186-9fae-530511f297be', 'd3e4f5a6-7b8c-4e93-8f23-4a5b6c7d8e33', '9ad9b9a7-fd88-4b51-9308-59174dce992e', 'subtopic'::public.curated_course_node_type, 'Social construction and empirical inquiry', 'Students learn to ask how deviance categories are made, sustained, contested, and measured.', 0),
  ('9b90c7bc-48e1-48b8-a349-71d13876002c', 'd3e4f5a6-7b8c-4e93-8f23-4a5b6c7d8e33', '001d019e-41eb-4186-9fae-530511f297be', 'concept'::public.curated_course_node_type, 'Claims-making', null, 0),
  ('a162a492-06b4-4797-844a-134d9f324e85', 'd3e4f5a6-7b8c-4e93-8f23-4a5b6c7d8e33', '001d019e-41eb-4186-9fae-530511f297be', 'concept'::public.curated_course_node_type, 'Institutional classification', null, 1),
  ('6beea467-7206-435f-8dde-93554f745d40', 'd3e4f5a6-7b8c-4e93-8f23-4a5b6c7d8e33', '001d019e-41eb-4186-9fae-530511f297be', 'concept'::public.curated_course_node_type, 'Evidence versus moral assumption', null, 2),
  ('c62ec988-4597-4b7e-a1ad-e7e9b5cf7f14', 'd3e4f5a6-7b8c-4e93-8f23-4a5b6c7d8e33', '9ad9b9a7-fd88-4b51-9308-59174dce992e', 'subtopic'::public.curated_course_node_type, 'Levels of analysis', 'This subtopic connects individual behavior with groups, organizations, communities, law, media, and political economy.', 1),
  ('9c9b72e4-da92-43f7-a27c-82aa9376be50', 'd3e4f5a6-7b8c-4e93-8f23-4a5b6c7d8e33', 'c62ec988-4597-4b7e-a1ad-e7e9b5cf7f14', 'concept'::public.curated_course_node_type, 'Micro interaction', null, 0),
  ('e7ab3d3e-2117-40ab-9c82-29e234ef74e1', 'd3e4f5a6-7b8c-4e93-8f23-4a5b6c7d8e33', 'c62ec988-4597-4b7e-a1ad-e7e9b5cf7f14', 'concept'::public.curated_course_node_type, 'Organizations and institutions', null, 1),
  ('e47c5943-242a-4a3e-b8a8-6caf4595b02b', 'd3e4f5a6-7b8c-4e93-8f23-4a5b6c7d8e33', 'c62ec988-4597-4b7e-a1ad-e7e9b5cf7f14', 'concept'::public.curated_course_node_type, 'Macro inequality and state power', null, 2),
  ('893c10cd-c9db-4cb6-9d2e-863324d8f96d', 'd3e4f5a6-7b8c-4e93-8f23-4a5b6c7d8e33', '9ad9b9a7-fd88-4b51-9308-59174dce992e', 'subtopic'::public.curated_course_node_type, 'Ethics of studying deviance', 'Students discuss how to study stigmatized groups, illegal behavior, and harmed communities responsibly.', 2),
  ('3ccd61f9-bf56-4f09-acfb-8fe8d7cb030c', 'd3e4f5a6-7b8c-4e93-8f23-4a5b6c7d8e33', '893c10cd-c9db-4cb6-9d2e-863324d8f96d', 'concept'::public.curated_course_node_type, 'Confidentiality and risk', null, 0),
  ('73178e9d-0dba-4875-8361-164f874fd2ab', 'd3e4f5a6-7b8c-4e93-8f23-4a5b6c7d8e33', '893c10cd-c9db-4cb6-9d2e-863324d8f96d', 'concept'::public.curated_course_node_type, 'Researcher positionality', null, 1),
  ('e0c318b2-6abf-4227-94f1-5547423990e4', 'd3e4f5a6-7b8c-4e93-8f23-4a5b6c7d8e33', '893c10cd-c9db-4cb6-9d2e-863324d8f96d', 'concept'::public.curated_course_node_type, 'Avoiding harm and sensationalism', null, 2),
  ('6d310c02-b979-4ac2-9506-9dbc8b668886', 'd3e4f5a6-7b8c-4e93-8f23-4a5b6c7d8e33', null, 'topic'::public.curated_course_node_type, 'Functionalist Theories: Durkheim, Anomie, and Strain', 'Functionalist theories ask what deviance does for social order and what happens when norms, goals, and institutions fall out of alignment. Students learn why deviance can reveal the boundaries and tensions of society.', 2),
  ('d44990f3-f935-40a4-87f2-0c6e5178cd18', 'd3e4f5a6-7b8c-4e93-8f23-4a5b6c7d8e33', '6d310c02-b979-4ac2-9506-9dbc8b668886', 'subtopic'::public.curated_course_node_type, 'Durkheim and the functions of deviance', 'Students examine deviance as normal, boundary-making, and sometimes a source of social change.', 0),
  ('9f4ab351-6ff9-4eca-8eea-6b24a4c184d2', 'd3e4f5a6-7b8c-4e93-8f23-4a5b6c7d8e33', 'd44990f3-f935-40a4-87f2-0c6e5178cd18', 'concept'::public.curated_course_node_type, 'Collective conscience', null, 0),
  ('637af23a-7fd7-4a11-9d0b-75104020175e', 'd3e4f5a6-7b8c-4e93-8f23-4a5b6c7d8e33', 'd44990f3-f935-40a4-87f2-0c6e5178cd18', 'concept'::public.curated_course_node_type, 'Boundary maintenance', null, 1),
  ('a3399dcf-1f46-4b7c-856f-e2467a5a6051', 'd3e4f5a6-7b8c-4e93-8f23-4a5b6c7d8e33', 'd44990f3-f935-40a4-87f2-0c6e5178cd18', 'concept'::public.curated_course_node_type, 'Deviance and innovation', null, 2),
  ('4ea8b488-935d-47ab-aac6-d31f9e541bec', 'd3e4f5a6-7b8c-4e93-8f23-4a5b6c7d8e33', '6d310c02-b979-4ac2-9506-9dbc8b668886', 'subtopic'::public.curated_course_node_type, 'Anomie and strain', 'This subtopic introduces how blocked opportunities and normlessness can produce deviant adaptations.', 1),
  ('420e13de-d112-47e7-a6ef-acfd6a4e540e', 'd3e4f5a6-7b8c-4e93-8f23-4a5b6c7d8e33', '4ea8b488-935d-47ab-aac6-d31f9e541bec', 'concept'::public.curated_course_node_type, 'Merton''s strain theory', null, 0),
  ('37f0ddc5-47cb-4c2b-bbff-d9f5def62b84', 'd3e4f5a6-7b8c-4e93-8f23-4a5b6c7d8e33', '4ea8b488-935d-47ab-aac6-d31f9e541bec', 'concept'::public.curated_course_node_type, 'Goals and institutionalized means', null, 1),
  ('5ae8a1f4-3bf5-42e4-9303-4c6fe5881731', 'd3e4f5a6-7b8c-4e93-8f23-4a5b6c7d8e33', '4ea8b488-935d-47ab-aac6-d31f9e541bec', 'concept'::public.curated_course_node_type, 'Adaptation types', null, 2),
  ('de52565a-74cd-4951-958f-7ba4848ca8b3', 'd3e4f5a6-7b8c-4e93-8f23-4a5b6c7d8e33', '6d310c02-b979-4ac2-9506-9dbc8b668886', 'subtopic'::public.curated_course_node_type, 'Contemporary strain perspectives', 'Students extend strain theory to stress, inequality, frustration, and coping.', 2),
  ('1d001b87-75f8-45fe-92ae-50510f3c5772', 'd3e4f5a6-7b8c-4e93-8f23-4a5b6c7d8e33', 'de52565a-74cd-4951-958f-7ba4848ca8b3', 'concept'::public.curated_course_node_type, 'General strain theory', null, 0),
  ('35a6773f-fda0-4d45-ae33-1d616a35d120', 'd3e4f5a6-7b8c-4e93-8f23-4a5b6c7d8e33', 'de52565a-74cd-4951-958f-7ba4848ca8b3', 'concept'::public.curated_course_node_type, 'Relative deprivation', null, 1),
  ('ceef9df0-a11e-4a9e-850e-e393b6400299', 'd3e4f5a6-7b8c-4e93-8f23-4a5b6c7d8e33', 'de52565a-74cd-4951-958f-7ba4848ca8b3', 'concept'::public.curated_course_node_type, 'Institutional strain', null, 2),
  ('ba135c8b-f3fc-465b-87d4-8c0daa6fc3e9', 'd3e4f5a6-7b8c-4e93-8f23-4a5b6c7d8e33', null, 'topic'::public.curated_course_node_type, 'Conflict Theories, Power, and the Making of Rules', 'Conflict theories shift attention from rule-breaking to rule-making. Students learn to ask who has the power to define deviance, whose harms are criminalized, and whose misconduct is normalized or protected.', 3);
