  ('670b0a62-ff1a-48b8-810f-1ee3be49f823', 'd3e4f5a6-7b8c-4e93-8f23-4a5b6c7d8e33', 'ba135c8b-f3fc-465b-87d4-8c0daa6fc3e9', 'subtopic'::public.curated_course_node_type, 'Power and legal classification', 'Students examine law as a social product shaped by conflict, interest, ideology, and institutional power.', 0),
  ('9bc35ab3-981f-40e1-8ca1-59020551de0a', 'd3e4f5a6-7b8c-4e93-8f23-4a5b6c7d8e33', '670b0a62-ff1a-48b8-810f-1ee3be49f823', 'concept'::public.curated_course_node_type, 'Lawmaking and enforcement', null, 0),
