  ('aecca306-a931-49d0-9e39-61c6ce0c0166', 'd3e4f5a6-7b8c-4e93-8f23-4a5b6c7d8e33', '670b0a62-ff1a-48b8-810f-1ee3be49f823', 'concept'::public.curated_course_node_type, 'Selective criminalization', null, 2),
  ('2f422eb7-40b3-49bd-94b8-e1ea55fe6682', 'd3e4f5a6-7b8c-4e93-8f23-4a5b6c7d8e33', 'ba135c8b-f3fc-465b-87d4-8c0daa6fc3e9', 'subtopic'::public.curated_course_node_type, 'Inequality and social control', 'This subtopic connects control institutions to class, race, gender, citizenship, disability, and sexuality.', 1),
  ('45ea5d1c-595c-4513-93a1-005b00b4f7cf', 'd3e4f5a6-7b8c-4e93-8f23-4a5b6c7d8e33', '2f422eb7-40b3-49bd-94b8-e1ea55fe6682', 'concept'::public.curated_course_node_type, 'Differential enforcement', null, 0),
  ('13aeca3f-bcd4-47a6-9a7b-c695a35d88f5', 'd3e4f5a6-7b8c-4e93-8f23-4a5b6c7d8e33', '2f422eb7-40b3-49bd-94b8-e1ea55fe6682', 'concept'::public.curated_course_node_type, 'Criminalization of poverty', null, 1),
  ('c346217b-7910-4cbd-b5aa-65b06cb9e291', 'd3e4f5a6-7b8c-4e93-8f23-4a5b6c7d8e33', '2f422eb7-40b3-49bd-94b8-e1ea55fe6682', 'concept'::public.curated_course_node_type, 'Control of marginalized groups', null, 2),
  ('3e7754bd-688b-41ea-9f34-da18641d9399', 'd3e4f5a6-7b8c-4e93-8f23-4a5b6c7d8e33', 'ba135c8b-f3fc-465b-87d4-8c0daa6fc3e9', 'subtopic'::public.curated_course_node_type, 'White-collar, corporate, and state deviance', 'Students study powerful actors whose harmful actions may be treated differently from street-level deviance.', 2),
  ('a1f7ec75-2275-4829-929d-4170415babc1', 'd3e4f5a6-7b8c-4e93-8f23-4a5b6c7d8e33', '3e7754bd-688b-41ea-9f34-da18641d9399', 'concept'::public.curated_course_node_type, 'Corporate crime', null, 0),
  ('70eee7aa-62aa-4683-b8bf-85ad64cb3d2b', 'd3e4f5a6-7b8c-4e93-8f23-4a5b6c7d8e33', '3e7754bd-688b-41ea-9f34-da18641d9399', 'concept'::public.curated_course_node_type, 'State crime and human rights', null, 1),
  ('b830279a-2f68-483d-845e-27c6d92ee3de', 'd3e4f5a6-7b8c-4e93-8f23-4a5b6c7d8e33', '3e7754bd-688b-41ea-9f34-da18641d9399', 'concept'::public.curated_course_node_type, 'Regulatory capture and impunity', null, 2),
  ('755c2aac-adef-47eb-8597-f04b05e64ca6', 'd3e4f5a6-7b8c-4e93-8f23-4a5b6c7d8e33', null, 'topic'::public.curated_course_node_type, 'Symbolic Interaction, Labeling, and Stigma', 'Interactionist theories show how deviance emerges through meanings, labels, identities, and social reactions. This unit is central for understanding stigma, moral entrepreneurship, and the consequences of being marked deviant.', 4),
  ('e8294c2f-0f7c-4e67-b5ec-5d348a750eeb', 'd3e4f5a6-7b8c-4e93-8f23-4a5b6c7d8e33', '755c2aac-adef-47eb-8597-f04b05e64ca6', 'subtopic'::public.curated_course_node_type, 'Labeling theory', 'Students learn how labels can amplify deviance by altering identity, opportunity, surveillance, and social treatment.', 0),
  ('f5fa65f4-1b36-40bf-a6ab-047449c70d2c', 'd3e4f5a6-7b8c-4e93-8f23-4a5b6c7d8e33', 'e8294c2f-0f7c-4e67-b5ec-5d348a750eeb', 'concept'::public.curated_course_node_type, 'Primary and secondary deviance', null, 0),
  ('f7abfd10-2eea-47ea-badb-7e99c848fabf', 'd3e4f5a6-7b8c-4e93-8f23-4a5b6c7d8e33', 'e8294c2f-0f7c-4e67-b5ec-5d348a750eeb', 'concept'::public.curated_course_node_type, 'Self-fulfilling prophecy', null, 1),
  ('0d97ebe3-94a3-498f-85d5-7f31bcfce640', 'd3e4f5a6-7b8c-4e93-8f23-4a5b6c7d8e33', 'e8294c2f-0f7c-4e67-b5ec-5d348a750eeb', 'concept'::public.curated_course_node_type, 'Deviant careers', null, 2),
  ('29f52d11-93f7-4830-83c3-d99177958ed8', 'd3e4f5a6-7b8c-4e93-8f23-4a5b6c7d8e33', '755c2aac-adef-47eb-8597-f04b05e64ca6', 'subtopic'::public.curated_course_node_type, 'Stigma and identity management', 'This subtopic introduces stigma as a social process that shapes interaction, disclosure, passing, covering, and resistance.', 1),
  ('5864e329-331c-4792-8ea7-975f5e1d9cca', 'd3e4f5a6-7b8c-4e93-8f23-4a5b6c7d8e33', '29f52d11-93f7-4830-83c3-d99177958ed8', 'concept'::public.curated_course_node_type, 'Discredited and discreditable identities', null, 0),
  ('b89405aa-5bcb-4641-a42a-b49781ff6b01', 'd3e4f5a6-7b8c-4e93-8f23-4a5b6c7d8e33', '29f52d11-93f7-4830-83c3-d99177958ed8', 'concept'::public.curated_course_node_type, 'Passing and covering', null, 1),
  ('4d715493-7c8f-415e-b62b-b4f17b644405', 'd3e4f5a6-7b8c-4e93-8f23-4a5b6c7d8e33', '29f52d11-93f7-4830-83c3-d99177958ed8', 'concept'::public.curated_course_node_type, 'Courtesy stigma', null, 2),
  ('7011101a-1e07-4da6-bfa7-9b6fd4fda882', 'd3e4f5a6-7b8c-4e93-8f23-4a5b6c7d8e33', '755c2aac-adef-47eb-8597-f04b05e64ca6', 'subtopic'::public.curated_course_node_type, 'Moral entrepreneurs and claims-making', 'Students study how individuals, groups, media, and institutions campaign to define behaviors or populations as problematic.', 2),
  ('05ed6268-ee84-4e3f-8646-4500eeeaaecf', 'd3e4f5a6-7b8c-4e93-8f23-4a5b6c7d8e33', '7011101a-1e07-4da6-bfa7-9b6fd4fda882', 'concept'::public.curated_course_node_type, 'Rule creators and rule enforcers', null, 0),
  ('6534473b-a5d5-4e9d-9cda-9004cbc3e181', 'd3e4f5a6-7b8c-4e93-8f23-4a5b6c7d8e33', '7011101a-1e07-4da6-bfa7-9b6fd4fda882', 'concept'::public.curated_course_node_type, 'Moral campaigns', null, 1),
  ('6b44bac2-ce41-4e92-a8ed-8318d40962cf', 'd3e4f5a6-7b8c-4e93-8f23-4a5b6c7d8e33', '7011101a-1e07-4da6-bfa7-9b6fd4fda882', 'concept'::public.curated_course_node_type, 'Counterclaims and resistance', null, 2),
  ('c79bf868-c352-4216-aa04-a0ff66deedd1', 'd3e4f5a6-7b8c-4e93-8f23-4a5b6c7d8e33', null, 'topic'::public.curated_course_node_type, 'Informal Social Control: Families, Peers, Schools, Workplaces, and Communities', 'Not all social control happens through law. This unit examines everyday mechanisms that encourage conformity, punish difference, or reproduce inequality before formal institutions ever intervene.', 5),
  ('3aab25da-84c8-4c3e-a2d1-2cca8246178e', 'd3e4f5a6-7b8c-4e93-8f23-4a5b6c7d8e33', 'c79bf868-c352-4216-aa04-a0ff66deedd1', 'subtopic'::public.curated_course_node_type, 'Socialization and conformity', 'Students examine how norms are learned through family, school, religion, peers, work, and community life.', 0),
  ('debe222d-5437-4a6d-b3b0-5a22189751f8', 'd3e4f5a6-7b8c-4e93-8f23-4a5b6c7d8e33', '3aab25da-84c8-4c3e-a2d1-2cca8246178e', 'concept'::public.curated_course_node_type, 'Internalization of norms', null, 0),
  ('0ea407a3-2a43-4068-b449-3db2f7f9f466', 'd3e4f5a6-7b8c-4e93-8f23-4a5b6c7d8e33', '3aab25da-84c8-4c3e-a2d1-2cca8246178e', 'concept'::public.curated_course_node_type, 'Peer pressure and belonging', null, 1),
  ('05c83008-2b08-4703-a796-cc069ecccd65', 'd3e4f5a6-7b8c-4e93-8f23-4a5b6c7d8e33', '3aab25da-84c8-4c3e-a2d1-2cca8246178e', 'concept'::public.curated_course_node_type, 'Conformity and identity', null, 2),
  ('358cb721-c854-423c-87e3-f108ab6e4ac2', 'd3e4f5a6-7b8c-4e93-8f23-4a5b6c7d8e33', 'c79bf868-c352-4216-aa04-a0ff66deedd1', 'subtopic'::public.curated_course_node_type, 'Informal sanctions and exclusion', 'This subtopic explores gossip, ridicule, shaming, ostracism, discipline, and reputational control.', 1),
  ('8d4c9804-277d-4893-b8f9-e20eb7a5f0da', 'd3e4f5a6-7b8c-4e93-8f23-4a5b6c7d8e33', '358cb721-c854-423c-87e3-f108ab6e4ac2', 'concept'::public.curated_course_node_type, 'Shame and embarrassment', null, 0),
  ('876cb5a7-e4a9-46ca-b546-6f54c7a3396a', 'd3e4f5a6-7b8c-4e93-8f23-4a5b6c7d8e33', '358cb721-c854-423c-87e3-f108ab6e4ac2', 'concept'::public.curated_course_node_type, 'Status loss', null, 1),
  ('5e443eef-449e-43b4-aee3-612d728c292b', 'd3e4f5a6-7b8c-4e93-8f23-4a5b6c7d8e33', '358cb721-c854-423c-87e3-f108ab6e4ac2', 'concept'::public.curated_course_node_type, 'Community exclusion', null, 2),
  ('d254ca6d-9e4e-4b21-91e0-c9a1dfcb8467', 'd3e4f5a6-7b8c-4e93-8f23-4a5b6c7d8e33', 'c79bf868-c352-4216-aa04-a0ff66deedd1', 'subtopic'::public.curated_course_node_type, 'Community control and collective efficacy', 'Students learn how social ties and shared expectations can reduce harm or intensify surveillance.', 2),
  ('2a460b4c-c2c5-4964-89d8-2f10fc70b0f6', 'd3e4f5a6-7b8c-4e93-8f23-4a5b6c7d8e33', 'd254ca6d-9e4e-4b21-91e0-c9a1dfcb8467', 'concept'::public.curated_course_node_type, 'Neighborhood social control', null, 0),
  ('e1966034-b6b0-4cb4-adc1-3013fc76626d', 'd3e4f5a6-7b8c-4e93-8f23-4a5b6c7d8e33', 'd254ca6d-9e4e-4b21-91e0-c9a1dfcb8467', 'concept'::public.curated_course_node_type, 'Collective efficacy', null, 1),
  ('6a052fce-85a6-4a81-af42-a3ef633058de', 'd3e4f5a6-7b8c-4e93-8f23-4a5b6c7d8e33', 'd254ca6d-9e4e-4b21-91e0-c9a1dfcb8467', 'concept'::public.curated_course_node_type, 'Informal justice and restorative practices', null, 2),
  ('4956ac9f-6a77-47ef-9441-130090686368', 'd3e4f5a6-7b8c-4e93-8f23-4a5b6c7d8e33', null, 'topic'::public.curated_course_node_type, 'Formal Social Control: Law, Bureaucracy, and Institutions', 'Formal social control includes rules, agencies, records, sanctions, professional authority, and bureaucratic procedures. Students learn how institutions transform behavior into cases, diagnoses, violations, and punishments.', 6),
  ('b72d0c4c-7a50-4b1f-835b-611a4062b849', 'd3e4f5a6-7b8c-4e93-8f23-4a5b6c7d8e33', '4956ac9f-6a77-47ef-9441-130090686368', 'subtopic'::public.curated_course_node_type, 'Law and legal authority', 'Students examine the role of criminal, civil, administrative, and regulatory law in defining and controlling deviance.', 0);
