  ('0b32ef6a-f082-453f-88fa-5c9fa47585da', 'd3e4f5a6-7b8c-4e93-8f23-4a5b6c7d8e33', '4956ac9f-6a77-47ef-9441-130090686368', 'subtopic'::public.curated_course_node_type, 'Treatment, discipline, and punishment', 'Students compare medical, therapeutic, educational, correctional, and managerial responses to deviance.', 2),
  ('fd681ba2-fb9d-4ef7-a8d7-aa51d2d4f7af', 'd3e4f5a6-7b8c-4e93-8f23-4a5b6c7d8e33', '0b32ef6a-f082-453f-88fa-5c9fa47585da', 'concept'::public.curated_course_node_type, 'Medicalization', null, 0),
  ('cf0fff36-9305-4dd1-8a00-8c5eebe752e5', 'd3e4f5a6-7b8c-4e93-8f23-4a5b6c7d8e33', '0b32ef6a-f082-453f-88fa-5c9fa47585da', 'concept'::public.curated_course_node_type, 'Disciplinary power', null, 1),
  ('30d11c64-ad56-4db5-874e-bcbb86ce3c46', 'd3e4f5a6-7b8c-4e93-8f23-4a5b6c7d8e33', '0b32ef6a-f082-453f-88fa-5c9fa47585da', 'concept'::public.curated_course_node_type, 'Punitive and rehabilitative models', null, 2),
  ('e491958f-f0da-458e-a572-aa953fee09f5', 'd3e4f5a6-7b8c-4e93-8f23-4a5b6c7d8e33', null, 'topic'::public.curated_course_node_type, 'Crime, Criminalization, and the Criminal Justice System', 'Crime is a major but not exclusive form of deviance. This unit connects sociological theories of deviance to criminal law, police, courts, corrections, and reform debates.', 7),
  ('6265564e-f1f2-4ef7-a1af-5f319c5f877f', 'd3e4f5a6-7b8c-4e93-8f23-4a5b6c7d8e33', 'e491958f-f0da-458e-a572-aa953fee09f5', 'subtopic'::public.curated_course_node_type, 'Crime as a legal and social category', 'Students distinguish legal definitions of crime from sociological definitions of harm, deviance, and social reaction.', 0),
  ('5c7a330a-b7e6-4162-936f-395b1102a990', 'd3e4f5a6-7b8c-4e93-8f23-4a5b6c7d8e33', '6265564e-f1f2-4ef7-a1af-5f319c5f877f', 'concept'::public.curated_course_node_type, 'Mala in se and mala prohibita', null, 0),
  ('bc7afc6b-a022-436a-aef5-070eee9ed3e9', 'd3e4f5a6-7b8c-4e93-8f23-4a5b6c7d8e33', '6265564e-f1f2-4ef7-a1af-5f319c5f877f', 'concept'::public.curated_course_node_type, 'Harm and victimization', null, 1),
  ('70a12448-c557-49b6-aa2a-8d1e38ae8308', 'd3e4f5a6-7b8c-4e93-8f23-4a5b6c7d8e33', '6265564e-f1f2-4ef7-a1af-5f319c5f877f', 'concept'::public.curated_course_node_type, 'Criminalization processes', null, 2),
  ('828e63bc-43f5-4404-bb84-ffde5e368071', 'd3e4f5a6-7b8c-4e93-8f23-4a5b6c7d8e33', 'e491958f-f0da-458e-a572-aa953fee09f5', 'subtopic'::public.curated_course_node_type, 'Police, courts, and corrections', 'This subtopic introduces the major institutions that process criminalized behavior.', 1),
  ('e856c3dc-0a33-404e-b0ac-ab6a35ad5c8a', 'd3e4f5a6-7b8c-4e93-8f23-4a5b6c7d8e33', '828e63bc-43f5-4404-bb84-ffde5e368071', 'concept'::public.curated_course_node_type, 'Police discretion', null, 0),
  ('eb002c6e-aafa-4377-a8bb-8ed9f03bba3e', 'd3e4f5a6-7b8c-4e93-8f23-4a5b6c7d8e33', '828e63bc-43f5-4404-bb84-ffde5e368071', 'concept'::public.curated_course_node_type, 'Prosecution and plea bargaining', null, 1),
  ('faa09fc0-54e5-4a5b-9b6d-d77654bebeda', 'd3e4f5a6-7b8c-4e93-8f23-4a5b6c7d8e33', '828e63bc-43f5-4404-bb84-ffde5e368071', 'concept'::public.curated_course_node_type, 'Jails, prisons, probation, and parole', null, 2),
  ('a2e581b1-f7e1-4e20-ae67-74bb716d932e', 'd3e4f5a6-7b8c-4e93-8f23-4a5b6c7d8e33', 'e491958f-f0da-458e-a572-aa953fee09f5', 'subtopic'::public.curated_course_node_type, 'Criminal justice policy models', 'Students compare due process, crime control, restorative, abolitionist, and public health approaches.', 2),
  ('12872f44-c2cd-47bd-93d9-82484020a751', 'd3e4f5a6-7b8c-4e93-8f23-4a5b6c7d8e33', 'a2e581b1-f7e1-4e20-ae67-74bb716d932e', 'concept'::public.curated_course_node_type, 'Due process versus crime control', null, 0),
  ('d74a4b4c-04a0-41b2-ab0a-027b8f41c964', 'd3e4f5a6-7b8c-4e93-8f23-4a5b6c7d8e33', 'a2e581b1-f7e1-4e20-ae67-74bb716d932e', 'concept'::public.curated_course_node_type, 'Restorative justice', null, 1),
  ('fef8364e-03f4-41ae-b607-bd3497979d79', 'd3e4f5a6-7b8c-4e93-8f23-4a5b6c7d8e33', 'a2e581b1-f7e1-4e20-ae67-74bb716d932e', 'concept'::public.curated_course_node_type, 'Reform and abolition debates', null, 2),
  ('7b1bfb7c-7778-420f-83fa-6af3d12485d6', 'd3e4f5a6-7b8c-4e93-8f23-4a5b6c7d8e33', null, 'topic'::public.curated_course_node_type, 'Measuring Deviance and Crime', 'A world-class course must teach students how deviance and crime are counted, missed, distorted, and interpreted. This unit builds empirical literacy for official data, surveys, ethnography, and mixed-method evidence.', 8),
  ('e1e42ef2-2370-4726-87bf-b0682522146f', 'd3e4f5a6-7b8c-4e93-8f23-4a5b6c7d8e33', '7b1bfb7c-7778-420f-83fa-6af3d12485d6', 'subtopic'::public.curated_course_node_type, 'Official statistics and administrative data', 'Students learn how police reports, court records, corrections data, and agency statistics are produced and limited.', 0),
  ('83dd98f5-7aac-4c86-9c27-d40b6292907a', 'd3e4f5a6-7b8c-4e93-8f23-4a5b6c7d8e33', 'e1e42ef2-2370-4726-87bf-b0682522146f', 'concept'::public.curated_course_node_type, 'UCR/NIBRS', null, 0),
  ('cebdfad8-90b4-4079-b6fc-e9b23c4dcede', 'd3e4f5a6-7b8c-4e93-8f23-4a5b6c7d8e33', 'e1e42ef2-2370-4726-87bf-b0682522146f', 'concept'::public.curated_course_node_type, 'Arrest and conviction data', null, 1),
  ('0fa9dbdc-0284-485d-a45a-d10181be74b8', 'd3e4f5a6-7b8c-4e93-8f23-4a5b6c7d8e33', 'e1e42ef2-2370-4726-87bf-b0682522146f', 'concept'::public.curated_course_node_type, 'Administrative bias', null, 2),
  ('8690d764-4c18-4ec2-bb08-85ad4d6aa81f', 'd3e4f5a6-7b8c-4e93-8f23-4a5b6c7d8e33', '7b1bfb7c-7778-420f-83fa-6af3d12485d6', 'subtopic'::public.curated_course_node_type, 'Victimization and self-report surveys', 'This subtopic introduces survey-based approaches that capture experiences often missing from official records.', 1),
  ('d00cec53-af7c-44a5-a048-66876b519254', 'd3e4f5a6-7b8c-4e93-8f23-4a5b6c7d8e33', '8690d764-4c18-4ec2-bb08-85ad4d6aa81f', 'concept'::public.curated_course_node_type, 'NCVS and victimization surveys', null, 0),
  ('b32deb65-4bec-4e32-befd-d1e3a0789802', 'd3e4f5a6-7b8c-4e93-8f23-4a5b6c7d8e33', '8690d764-4c18-4ec2-bb08-85ad4d6aa81f', 'concept'::public.curated_course_node_type, 'Self-report delinquency studies', null, 1),
  ('0768584c-2dee-4999-a829-727a20366cd1', 'd3e4f5a6-7b8c-4e93-8f23-4a5b6c7d8e33', '8690d764-4c18-4ec2-bb08-85ad4d6aa81f', 'concept'::public.curated_course_node_type, 'Sampling and reporting bias', null, 2),
  ('95d2c0fc-5910-41c7-826c-1afd20dbeab3', 'd3e4f5a6-7b8c-4e93-8f23-4a5b6c7d8e33', '7b1bfb7c-7778-420f-83fa-6af3d12485d6', 'subtopic'::public.curated_course_node_type, 'Qualitative and ethnographic evidence', 'Students examine how interviews, observation, archival work, and case studies reveal meanings and institutions.', 2),
  ('57ea3220-63ef-406f-ba19-1642ee8cab58', 'd3e4f5a6-7b8c-4e93-8f23-4a5b6c7d8e33', '95d2c0fc-5910-41c7-826c-1afd20dbeab3', 'concept'::public.curated_course_node_type, 'Field access and ethics', null, 0),
  ('95f3356e-1691-4ea2-a3f2-c6021aa567d3', 'd3e4f5a6-7b8c-4e93-8f23-4a5b6c7d8e33', '95d2c0fc-5910-41c7-826c-1afd20dbeab3', 'concept'::public.curated_course_node_type, 'Thick description', null, 1),
  ('ff4f0ea2-4df2-4579-9440-f1c348135d93', 'd3e4f5a6-7b8c-4e93-8f23-4a5b6c7d8e33', '95d2c0fc-5910-41c7-826c-1afd20dbeab3', 'concept'::public.curated_course_node_type, 'Triangulation', null, 2),
  ('66811ae7-aeaa-4f27-8d03-4683362fce36', 'd3e4f5a6-7b8c-4e93-8f23-4a5b6c7d8e33', null, 'topic'::public.curated_course_node_type, 'Policing, Surveillance, and Everyday Regulation', 'This unit examines policing as both a formal institution and a broader social practice of monitoring, sorting, and regulating people. Students analyze discretion, technology, legitimacy, and accountability.', 9),
  ('eaf33ab6-4e2c-42f2-aa59-e0057d8b4edf', 'd3e4f5a6-7b8c-4e93-8f23-4a5b6c7d8e33', '66811ae7-aeaa-4f27-8d03-4683362fce36', 'subtopic'::public.curated_course_node_type, 'Police discretion and legitimacy', 'Students study how officers and agencies decide whom to stop, search, warn, arrest, or refer.', 0),
  ('1cda4215-5e8e-4d4a-a1bd-a771f6167ac7', 'd3e4f5a6-7b8c-4e93-8f23-4a5b6c7d8e33', 'eaf33ab6-4e2c-42f2-aa59-e0057d8b4edf', 'concept'::public.curated_course_node_type, 'Discretion and selective enforcement', null, 0);
